from openpyxl import load_workbook

# Load the workbook
wb = load_workbook('book.xlsx')

# List all sheet names
print("Sheet names:", wb.sheetnames)

# Examine the Sales sheet
ws_sales = wb['Sales']
print("\n=== Sales Sheet Structure ===")
print("Max row:", ws_sales.max_row)
print("Max column:", ws_sales.max_column)

# Print all rows with data
print("\nSales data (first 15 rows):")
for row in ws_sales.iter_rows(min_row=1, max_row=15, values_only=False):
    row_data = []
    for cell in row:
        if cell.value is not None:
            # Show formula if it's a formula, otherwise show value
            if isinstance(cell.value, str) and cell.value.startswith('='):
                row_data.append(f"FORMULA: {cell.value}")
            else:
                row_data.append(str(cell.value))
        else:
            row_data.append("")
    if any(row_data):  # Only print non-empty rows
        print(f"Row {row[0].row}: {row_data}")

# Check the Summary sheet
if 'Summary' in wb.sheetnames:
    ws_summary = wb['Summary']
    print("\n=== Summary Sheet (first 20 rows) ===")
    for row in ws_summary.iter_rows(min_row=1, max_row=20, values_only=False):
        row_data = []
        for cell in row:
            if cell.value is not None:
                if isinstance(cell.value, str) and cell.value.startswith('='):
                    row_data.append(f"FORMULA: {cell.value}")
                else:
                    row_data.append(str(cell.value))
            else:
                row_data.append("")
        if any(row_data):
            print(f"Row {row[0].row}: {row_data}")

